const menu=document.querySelector('.menu');const nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});document.querySelectorAll('.service').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)document.querySelectorAll('.service').forEach(other=>{if(other!==item)other.open=false})}));
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const statsObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target;statsObserver.unobserve(el);const end=Number(el.dataset.count),dec=Number(el.dataset.decimals),prefix=el.dataset.prefix;const start=performance.now();const draw=now=>{const p=reduceMotion?1:Math.min((now-start)/1600,1);el.textContent=prefix+(end*(1-Math.pow(1-p,3))).toLocaleString('pt-BR',{minimumFractionDigits:dec,maximumFractionDigits:dec});if(p<1)requestAnimationFrame(draw)};requestAnimationFrame(draw)}),{threshold:.5});document.querySelectorAll('[data-count]').forEach(el=>statsObserver.observe(el));
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}}),{threshold:.06});document.querySelectorAll('.section-heading,.about-grid,.wide-photo,.methodology>div,.contact-copy,.articles').forEach(el=>{el.classList.add('reveal');revealObserver.observe(el)});
const partners=document.querySelector('.partner-grid');[...(partners?.children||[])].forEach(el=>{const copy=el.cloneNode(true);copy.setAttribute('aria-hidden','true');partners.append(copy)});

// Staggered entrance for the brand strip, solution cards and case logos.
document.querySelectorAll('.hero-affiliations,.service,.logo-grid>div,.stats>div').forEach((el,i)=>{el.style.setProperty('--entry-delay',`${(i%4)*65}ms`);el.classList.add('reveal','stagger');revealObserver.observe(el)});

const arrowIcon='<svg class="button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>';const calendarIcon='<svg class="button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5M17 3v5M3 11h18M8 15h3"/></svg>';document.querySelectorAll('.button,.header-cta,.mobile-contact').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('beforeend',/agendar|agendamento|diagnóstico/i.test(el.textContent)?calendarIcon:arrowIcon)});
document.querySelectorAll('.content-section,.directory-card').forEach((el,i)=>{el.classList.add('reveal');revealObserver.observe(el)});

// Hover opens services on pointer devices; native details keep touch and keyboard support.
const finePointer=matchMedia('(hover:hover) and (pointer:fine)');
document.querySelectorAll('.service').forEach(item=>{let hoverTimer,scrollTimer;const cancel=()=>{clearTimeout(hoverTimer);clearTimeout(scrollTimer)};item.addEventListener('mouseenter',()=>{if(!finePointer.matches||item.open)return;hoverTimer=setTimeout(()=>{item.open=true;scrollTimer=setTimeout(()=>{if(!item.matches(':hover'))return;const box=item.getBoundingClientRect();if(box.bottom>innerHeight-24||box.top<80)item.scrollIntoView({behavior:reduceMotion?'instant':'smooth',block:'start'})},150)},180)});item.addEventListener('mouseleave',cancel);item.addEventListener('focusout',()=>clearTimeout(scrollTimer))});
const methodPanels=[...document.querySelectorAll('.method-panel')];methodPanels.forEach(panel=>{let hoverTimer;panel.addEventListener('mouseenter',()=>{if(finePointer.matches)hoverTimer=setTimeout(()=>{methodPanels.forEach(other=>other.open=other===panel)},120)});panel.addEventListener('mouseleave',()=>clearTimeout(hoverTimer));panel.addEventListener('toggle',()=>{if(panel.open)methodPanels.forEach(other=>{if(other!==panel)other.open=false})})});
